def is_type_A(N):
    """
    Computes whether N is of Type A (A wins) or Type B (B wins) for the given game.
    """
    if N <= 0:
        raise ValueError("N must be a positive integer.")
    if N == 1:
        return True

    dp = [False] * (N + 1)

    for n in range(N - 1, 0, -1):

        moves = []

        n1 = n + 1
        if n1 <= N:
            moves.append(n1)
            if n1 == N:
                dp[n] = True
                continue

        n2 = 2 * n
        if n2 <= N:
            moves.append(n2)
            if n2 == N:
                dp[n] = True
                continue

        if not dp[n]: 
            can_win = False
            for s in moves:
                if not dp[s]:
                    can_win = True
                    break

            dp[n] = can_win

    return dp[1]

# Search for the least N > 400 such that N is Type B (is_type_A(N) is False).
target_N = None
start_N = 401
end_N = 501 # Searching up to 500

for N in range(start_N, end_N):
    if not is_type_A(N):
        target_N = N
        break

if target_N is not None:
    print(f"The least N > 400 that is Type B is: {target_N}")
else:
    print("No Type B number found in the range 401 <= N <= 500.")

def solve_game(N):
    # P[k] = True if k is a P-position (losing for current player)
    # P[k] = False if k is an N-position (winning for current player)
    P = {}

    for k in range(N - 1, 0, -1):

        moves = set()
        if k + 1 <= N:
            moves.add(k + 1)
        if 2 * k <= N:
            moves.add(2 * k)

        is_P = True

        if not moves:
            continue 

        for next_state in moves:
            if next_state == N:
                is_P = False
                break

            # If we haven't calculated P[next_state] yet, it means next_state > k.
            # Since we iterate backwards, P[next_state] must be defined.
            if next_state not in P:
                # This case should theoretically not be hit if iteration is correct
                continue 

            if not P[next_state]:
                # Next state is N (winning for next player). This move is bad for current player.
                # If ALL moves are bad, k is P.
                pass
            else:
                # Next state is P (losing for next player). This move guarantees a win for current player.
                # If we find one such move, k is N (winning for current player).
                is_P = False
                break

        P[k] = is_P

    return P[1]

# Search for the least N > 400 such that solve_game(N) returns True (Type B)
N = 401
while True:
    if solve_game(N):
        print(f"Found Type B number: N = {N}")
        break
    N += 1
